node -e "
const XLSX = require('xlsx');

// Create a new workbook
const wb = XLSX.utils.book_new();

// Data from the extracted PDF text
const data = [
  ['Source', 'Extracted Text'],
  ['Title', 'Employee Handbook'],
  ['Body',  'Welcome to the company. This handbook outlines our policies.']
];

// Create worksheet and append to workbook
const ws = XLSX.utils.aoa_to_sheet(data);

// Set column widths for readability
ws['!cols'] = [
  { wch: 10 },
  { wch: 60 }
];

XLSX.utils.book_append_sheet(wb, ws, 'Extracted Text');

// Write the file
XLSX.writeFile(wb, '/workspace/testbed/docs/handbook_extracted.xlsx');
console.log('Excel file created successfully.');
"

